import csv
import io
import re
from typing import Dict, List, Optional, Tuple


EXPECTED_WIDTH = 9


def _parse_record(record: str) -> List[str]:
    try:
        rows = list(csv.reader(io.StringIO(record), delimiter=",", quotechar='"',
                               doublequote=True, strict=False))
    except csv.Error:
        return record.rstrip("\r\n").split(",")
    if not rows:
        return []
    if len(rows) == 1:
        return rows[0]
    result = rows[0]
    for extra in rows[1:]:
        if result:
            result[-1] += "\n" + (extra[0] if extra else "")
            result.extend(extra[1:])
        else:
            result.extend(extra)
    return result


def _header_score(row: List[str]) -> int:
    if not row:
        return -100
    clues = {
        "date", "time", "qty", "quantity", "productid", "product",
        "price", "amount", "cost", "producttype", "type",
        "productdescription", "description", "url", "link",
        "comments", "comment", "notes", "note"
    }
    score = 0
    seen = set()
    for value in row:
        name = re.sub(r"[^a-z0-9]+", "", value.lower().lstrip("\ufeff"))
        if name in clues:
            score += 4
        elif re.search(r"(date|time|price|amount|quantity|description|comment|url|id)$", name):
            score += 2
        if name and name not in seen:
            score += 1
            seen.add(name)
    if len(row) == EXPECTED_WIDTH:
        score += 5
    if len(seen) != len(row):
        score -= 2
    return score


def _find_header_offset(raw_csv: str) -> int:
    lines = raw_csv.splitlines(True)
    offset = 0
    best_offset = 0
    best_score = -1000

    for line in lines[:100]:
        candidate = line.rstrip("\r\n")
        row = _parse_record(candidate)
        score = _header_score(row)
        if len(row) == EXPECTED_WIDTH and score > best_score:
            best_score = score
            best_offset = offset
        if len(row) == EXPECTED_WIDTH and score >= 18:
            return offset
        offset += len(line)

    if best_score >= 10:
        return best_offset
    return 0


def _logical_records(text: str) -> List[str]:
    records: List[str] = []
    start = 0
    i = 0
    in_quotes = False
    field_start = True

    while i < len(text):
        ch = text[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < len(text) and text[i + 1] == '"':
                    i += 2
                    continue
                in_quotes = False
            i += 1
            continue

        if ch == '"' and field_start:
            in_quotes = True
            field_start = False
            i += 1
            continue

        if ch == ",":
            field_start = True
            i += 1
            continue

        if ch in "\r\n":
            end = i
            if ch == "\r" and i + 1 < len(text) and text[i + 1] == "\n":
                i += 2
            else:
                i += 1
            records.append(text[start:end])
            start = i
            field_start = True
            continue

        if field_start and ch in " \t":
            i += 1
            continue

        field_start = False
        i += 1

    if start < len(text):
        records.append(text[start:])
    elif text and text[-1] not in "\r\n":
        records.append("")

    return records


def _replace_unquoted_semicolons(record: str) -> str:
    output: List[str] = []
    i = 0
    in_quotes = False
    field_start = True

    while i < len(record):
        ch = record[i]

        if in_quotes:
            output.append(ch)
            if ch == '"':
                if i + 1 < len(record) and record[i + 1] == '"':
                    output.append('"')
                    i += 2
                    continue
                in_quotes = False
            i += 1
            continue

        if ch == '"' and field_start:
            in_quotes = True
            field_start = False
            output.append(ch)
        elif ch in ",;":
            output.append(",")
            field_start = True
        else:
            output.append(ch)
            if not (field_start and ch in " \t"):
                field_start = False
        i += 1

    return "".join(output)


def _column_kind(name: str) -> str:
    normalized = re.sub(r"[^a-z0-9]+", "", name.lower())
    if "date" in normalized:
        return "date"
    if "time" in normalized:
        return "time"
    if normalized in ("qty", "quantity", "count", "units") or "quantity" in normalized:
        return "integer"
    if any(word in normalized for word in ("price", "amount", "cost")):
        return "money"
    if any(word in normalized for word in ("url", "uri", "link", "website")):
        return "url"
    if normalized.endswith("id") or normalized in ("id", "sku", "code"):
        return "id"
    if any(word in normalized for word in ("comment", "note", "remark")):
        return "comment"
    return "text"


def _value_score(value: str, kind: str) -> int:
    stripped = value.strip()

    if not stripped:
        return 1 if kind in ("comment", "text") else -1

    if kind == "date":
        if re.fullmatch(r"\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}", stripped):
            return 7
        return -5

    if kind == "time":
        if re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?(?:\s*[APap][Mm])?", stripped):
            return 7
        return -5

    if kind == "integer":
        return 7 if re.fullmatch(r"[+-]?\d+", stripped) else -6

    if kind == "money":
        if re.fullmatch(r"[\$€£¥]?\s*[+-]?(?:\d+(?:,\d{3})*|\d*)(?:\.\d+)?", stripped):
            return 7
        return -7

    if kind == "url":
        if re.match(r"(?i)^(?:https?|ftp)://", stripped):
            return 7
        if re.match(r"(?i)^www\.", stripped):
            return 5
        return -5

    if kind == "id":
        if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.:/#-]*", stripped):
            if re.search(r"\d", stripped):
                return 5
            return 1
        return -3

    if kind == "comment":
        return 2

    return 2


def _align_fields(fields: List[str], columns: List[str]) -> Tuple[int, List[str]]:
    kinds = [_column_kind(column) for column in columns]
    source_count = len(fields)
    target_count = len(columns)
    memo: Dict[Tuple[int, int], Tuple[int, List[str]]] = {}

    def solve(source_index: int, target_index: int) -> Tuple[int, List[str]]:
        key = (source_index, target_index)
        if key in memo:
            return memo[key]

        if target_index == target_count:
            result = (-3 * (source_count - source_index), [])
            memo[key] = result
            return result

        if source_index == source_count:
            missing = target_count - target_index
            result = (-2 * missing, [""] * missing)
            memo[key] = result
            return result

        best_score = -10 ** 9
        best_row: List[str] = []

        tail_score, tail_row = solve(source_index, target_index + 1)
        score = tail_score + _value_score("", kinds[target_index]) - 2
        if score > best_score:
            best_score = score
            best_row = [""] + tail_row

        tail_score, tail_row = solve(source_index + 1, target_index)
        score = tail_score - 3
        if score > best_score:
            best_score = score
            best_row = tail_row

        remaining_sources = source_count - source_index
        remaining_targets = target_count - target_index
        maximum_group = min(remaining_sources, max(1, remaining_sources - remaining_targets + 2), 5)

        for count in range(1, maximum_group + 1):
            value = ",".join(fields[source_index:source_index + count])
            tail_score, tail_row = solve(source_index + count, target_index + 1)
            merge_penalty = 2 * (count - 1)
            score = _value_score(value, kinds[target_index]) + tail_score - merge_penalty
            if score > best_score:
                best_score = score
                best_row = [value] + tail_row

        result = (best_score, best_row)
        memo[key] = result
        return result

    return solve(0, 0)


def _repair_record(record: str, columns: List[str]) -> List[str]:
    standard = _parse_record(record)
    width = len(columns)

    if len(standard) == width:
        return standard

    candidates: List[List[str]] = [standard]
    if ";" in record:
        alternate_text = _replace_unquoted_semicolons(record)
        alternate = _parse_record(alternate_text)
        if alternate != standard:
            candidates.append(alternate)

    best_score = -10 ** 9
    best_row = [""] * width

    for candidate in candidates:
        score, aligned = _align_fields(candidate, columns)
        score -= abs(len(candidate) - width)
        if score > best_score:
            best_score = score
            best_row = aligned

    if len(best_row) < width:
        best_row.extend([""] * (width - len(best_row)))
    elif len(best_row) > width:
        best_row = best_row[:width - 1] + [",".join(best_row[width - 1:])]

    return best_row


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if not raw_csv:
        return {"columns": [], "rows": []}

    header_offset = _find_header_offset(raw_csv)
    records = _logical_records(raw_csv[header_offset:])

    header_index: Optional[int] = None
    columns: List[str] = []

    for index, record in enumerate(records):
        if not record.strip():
            continue
        row = _parse_record(record)
        if header_index is None:
            header_index = index
            columns = row
            break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = [value.lstrip("\ufeff").strip() for value in columns]
    if not columns:
        return {"columns": [], "rows": []}

    rows: List[List[str]] = []
    for record in records[header_index + 1:]:
        if not record.strip():
            continue
        rows.append(_repair_record(record, columns))

    return {"columns": columns, "rows": rows}
